package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000003

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(reader, &n)

	if n == 0 {
		fmt.Println(1)
		return
	}

	pow2 := powMod(2, n-1, MOD)
	ans := (pow2 * pow2) % MOD
	ans = (ans + MOD - pow2) % MOD
	fmt.Println(ans)
}

func powMod(a, b, mod int) int {
	res := 1
	a %= mod
	for b > 0 {
		if b&1 == 1 {
			res = (res * a) % mod
		}
		a = (a * a) % mod
		b >>= 1
	}
	return res
}
